//
// The Synth FX default pack, as the firmware carries it (synthfxPack.inc, generated by
// tools/synthfx/build_pack.py --embed from synthfx-sdk/pack/). Written to /SynthFX/ for each
// file that is missing there, or that is a file an earlier release shipped (pluginPack.h).
// In flash.

#include "modsBuild.h"

#if MT_HAS_SYNTHFX

#include "synthfxPlugins.h"

namespace mods
{
namespace synthfx
{
namespace plugins
{

namespace
{
#include "synthfxPack.inc"
} // namespace

size_t packCount()
{
    return sizeof(kPack) / sizeof(kPack[0]);
}

const PackFile& packAt(size_t index)
{
    return kPack[index < packCount() ? index : 0];
}

// The host tests and the rig (its shim's modsBuild.h) may put a table in place of kShipped
#if defined(MT_HOST_TEST) || defined(MT_SHIPPED_FOR_TESTS)
namespace
{
const ShippedFile* testShipped = nullptr;
size_t testShippedCount = 0;
} // namespace

void shippedForTests(const ShippedFile* list, size_t count)
{
    testShipped = list;
    testShippedCount = count;
}
#endif

size_t shippedCount()
{
#if defined(MT_HOST_TEST) || defined(MT_SHIPPED_FOR_TESTS)
    if (testShipped != nullptr)
    {
        return testShippedCount;
    }
#endif
    return kShippedCount;
}

const ShippedFile* shippedList()
{
#if defined(MT_HOST_TEST) || defined(MT_SHIPPED_FOR_TESTS)
    if (testShipped != nullptr)
    {
        return testShipped;
    }
#endif
    return kShipped;
}

} // namespace plugins
} // namespace synthfx
} // namespace mods

#endif // MT_HAS_SYNTHFX
